'use strict';
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let feedLimit=30;
let state=null,archive=[],tab='life',worldType='map',audio=null,musicTimer=null,soundOn=false,storageFailed=false;
try{archive=JSON.parse(localStorage.getItem('aether-archive')||'[]');if(!Array.isArray(archive))archive=[];const saved=JSON.parse(localStorage.getItem('aether-life')||'null');if(saved)state=Engine.hydrate(saved)}catch(e){storageFailed=true}
const labels={health:'สุขภาพ',joy:'ความสุข',power:'พลังกาย',magic:'พลังเวท',wisdom:'ปัญญา',bond:'สายสัมพันธ์',fame:'ชื่อเสียง'};
function fresh(){const s=Engine.create(crypto.getRandomValues(new Uint32Array(1))[0],archive.length);s.accepted=false;Simulation.ensure(s);return s}
let isNew=!state;if(!state)state=fresh();Narrative.ensure(state);if(!state.dead&&!state.diary.entries.length)Narrative.passage(state,'arrival');
let screen='welcome',birthTimer=null,birthToken=0;
let playbackPrefs={};try{playbackPrefs=JSON.parse(localStorage.getItem('aether-playback')||'{}')||{}}catch(e){}
const clock=Autoplay.create({state:()=>state,blocked:()=>document.hidden||screen!=='playing'||tab!=='life'||($('#modal').open&&$('#modal').dataset.mode!=='decision'),finish:()=>record(),changed:()=>render(),preferences:p=>{try{localStorage.setItem('aether-playback',JSON.stringify(p))}catch(e){}}},playbackPrefs);
function clockMarkup(){const p=clock.prefs;return `<section class="playback panel" aria-label="ควบคุมการเดินชีวิต"><div class="playback-row"><span class="playback-year">ปี ${WorldTimeline.year(state)}</span><button id="playPause" class="secondary" aria-pressed="false">❚❚ หยุดพัก</button><button id="autoToggle" class="secondary" aria-pressed="${p.auto}">${p.auto?'✧ ตัดสินใจแทน: เปิด':'✧ ตัดสินใจแทน: ปิด'}</button><div class="speed-group" aria-label="ความเร็ว">${clock.speeds.map(v=>`<button data-speed="${v}" aria-pressed="${v===p.speed}" class="${v===p.speed?'active':''}">${v}×</button>`).join('')}</div><button id="skipTime" class="secondary">ไปเหตุการณ์ถัดไป »</button></div><details class="playback-settings"><summary>ตั้งค่าการเดินชีวิต</summary><div class="playback-row playback-options"><label>หนึ่งชีวิต ≈ <select id="lifePace" aria-label="ระยะเวลาหนึ่งชีวิต">${[5,30,60,90].map(v=>`<option value="${v}" ${p.minutes===v?'selected':''}>${v} นาที</option>`).join('')}</select></label><label>แนวทาง <select id="autoStyle" aria-label="แนวทางการตัดสินใจ">${[['balanced','สมดุล'],['safe','รอบคอบ'],['ambitious','ทะเยอทะยาน'],['kind','ใส่ใจผู้อื่น']].map(([k,v])=>`<option value="${k}" ${p.style===k?'selected':''}>${v}</option>`).join('')}</select></label><label>จังหวะอ่าน <select id="readingPace" aria-label="จังหวะเรื่องเล่า">${[[7,'กระชับ'],[14,'ปกติ'],[22,'ค่อย ๆ อ่าน']].map(([k,v])=>`<option value="${k}" ${p.reading===k?'selected':''}>${v}</option>`).join('')}</select></label></div></details><span id="clockStatus" role="status" aria-live="off"></span><div class="clock-track" role="progressbar" aria-label="ความคืบหน้าของเวลา" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i id="clockProgress"></i></div></section>`}
function bindClock(){if(!$('#playPause'))return;$('#playPause').onclick=()=>clock.pause();$('#autoToggle').onclick=()=>clock.set({auto:!clock.prefs.auto});document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>clock.set({speed:+b.dataset.speed}));$('#lifePace').onchange=e=>clock.set({minutes:+e.target.value});$('#autoStyle').onchange=e=>clock.set({style:e.target.value});$('#readingPace').onchange=e=>clock.set({reading:+e.target.value});$('#skipTime').onclick=()=>clock.skip();paintClock()}
function paintClock(){if(!$('#clockStatus'))return;const c=clock.status(),s=state;const text={ended:'การเดินทางจบลงแล้ว',paused:'หยุดพัก · กดเล่นต่อเมื่อพร้อม',away:'พักเวลาระหว่างอ่านหน้าต่างอื่น',journey:'เดือน '+c.month+' · อีก '+Math.max(.1,c.remaining).toFixed(1)+' วินาทีถึงช่วงถัดไป · '+clock.prefs.speed+'×',outcome:'กำลังอ่านผล · ชีวิตจะเดินต่อใน '+Math.ceil(c.remaining)+' วินาที',decision:'จะเลือก “'+(s.event.choices[c.selected]?.label||'กำลังพิจารณา')+'” ใน '+Math.ceil(c.remaining)+' วินาที',waiting:'เวลาหยุดรอคุณตัดสินใจ'};$('#clockStatus').textContent=text[c.kind];$('#playPause').textContent=c.paused?'▶ เล่นต่อ':'❚❚ หยุดพัก';$('#playPause').setAttribute('aria-pressed',String(c.paused));$('#skipTime').disabled=s.dead||!!s.calendar?.pending;document.querySelectorAll('.playback button,.playback select').forEach(b=>{if(b.id!=='skipTime')b.disabled=s.dead});const progress=c.kind==='journey'?c.yearsProgress:c.kind==='decision'||c.kind==='outcome'?c.progress:0;$('#clockProgress').style.width=progress*100+'%';$('#clockProgress').parentElement.setAttribute('aria-valuenow',String(Math.round(progress*100)));document.querySelectorAll('[data-choice]').forEach(b=>{const chosen=c.kind==='decision'&&+b.dataset.choice===c.selected;b.classList.toggle('autopick',chosen);b.setAttribute('aria-label',b.textContent+(chosen?' · คำตอบอัตโนมัติที่กำลังนับถอยหลัง':''))});DecisionPopup.paint(c)}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
let storageReady=false,lastBackupAt=0,backupTimer=null;
function backupLife(force=false){const now=Date.now(),wait=2000-(now-lastBackupAt);if(!force&&wait>0){if(!backupTimer)backupTimer=setTimeout(()=>{backupTimer=null;backupLife(true)},wait);return}if(backupTimer){clearTimeout(backupTimer);backupTimer=null}lastBackupAt=now;try{localStorage.setItem('aether-life',JSON.stringify(state));if(!storageReady)localStorage.setItem('aether-archive',JSON.stringify(archive))}catch(e){if(!storageFailed){toast('พื้นที่บันทึกสำรองเต็ม โปรดส่งออกเซฟเก็บไว้');storageFailed=true}}}
function save(force=false){state.savedAt=Date.now();state.saveRevision=(Number.isSafeInteger(state.saveRevision)?state.saveRevision:0)+1;if(storageReady){LifeStorage.save(state,archive).then(()=>{try{localStorage.removeItem('aether-archive')}catch(e){}}).catch(()=>{toast('บันทึกเรื่องเล่าไม่ได้ โปรดส่งออกเซฟสำรอง')})}backupLife(force===true);$('#count').textContent=archive.length}

function modal(html,mode='general'){const d=$('#modal');d.dataset.mode=mode;d.classList.toggle('decision-modal',mode==='decision');$('#modalBody').innerHTML=html;d.showModal();d.scrollTop=0}
function ctx(t){return esc(WorldLore.fill(state,t,state.event?.context||WorldLore.context(state)))}
function lifeStage(){return LifeGrowth.stage(state).name}
function render(){GameLanguage.register(state);const anchor=[...document.querySelectorAll('.feed-moment')].find(e=>e.getBoundingClientRect().bottom>100),anchorId=anchor?.querySelector('[data-entry]')?.dataset.entry,anchorTop=anchor?.getBoundingClientRect().top;const intro=$('.intro');if(intro)intro.hidden=true;document.querySelector('header nav').hidden=screen!=='playing';document.body.dataset.screen=screen;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#count').textContent=archive.length;if(screen==='welcome'){welcome();return}if(screen==='rolling'){rollingPage();return}if(screen==='birth'){birthPage();return}if(tab==='world'){world();return}if(tab==='archive'){archives();return}life();if(anchorId&&anchorTop<window.innerHeight){const next=document.querySelector('.feed-moment [data-entry="'+anchorId+'"]')?.closest('.feed-moment');if(next)window.scrollBy(0,next.getBoundingClientRect().top-anchorTop)}}
const welcomePeoples=[0,1,36,12,58,64,49,57,60,55,31,69];
let welcomeIndex=1,introElapsed=0,lastIntroFrame=0;
function welcomeSample(){return {race:welcomePeoples[welcomeIndex],kingdom:[0,1,3,7,12,8,10,15,13,14,12,6][welcomeIndex],seed:7214,rank:1,look:{hair:welcomeIndex%6,coat:welcomeIndex%8}}}
function drawIntroArt(){
 const stage=$('#welcomeScene');if(stage)Illustration.drawWelcome(stage,welcomeSample(),introElapsed);
 const preview=$('#birthPreview');if(preview)Illustration.drawRacePreview(preview,state,introElapsed);
 const roll=$('#rollPreview');if(roll)Illustration.drawRacePreview(roll,{...state,race:+roll.dataset.race,kingdom:+roll.dataset.kingdom},introElapsed);
}
function refreshWelcomeSample(){const sample=welcomeSample();$('#sampleRace').textContent=RACES[sample.race][0];$('#sampleRealm').textContent=KINGDOMS[sample.kingdom][0];$('#sampleNumber').textContent=(welcomeIndex+1)+' / '+welcomePeoples.length;$('#welcomeScene').setAttribute('aria-label','ตัวอย่างชาว'+RACES[sample.race][0]+' ใน'+KINGDOMS[sample.kingdom][0]);drawIntroArt()}
function welcome(){const resume=state.accepted!==false&&(state.turn>0||state.age>0||state.accepted);app.innerHTML=`<section class="classic-start start-v12"><p class="start-kicker">1 in 10 Billion <span>FANTASY</span></p><h1>โลกกว้างใหญ่<br>ชีวิตต่อไปจะเป็นใคร?</h1><p class="start-description">เพื่อนต่างเผ่า คำสัญญาที่ยังจำได้ และบ้านที่รอคุณ<br>ชีวิตเดินไปเอง คุณเลือกสิ่งที่จะทิ้งไว้ในใจใคร</p><div class="start-world"><canvas id="welcomeScene" width="480" height="180" role="img" aria-label="ตัวอย่างโลกแฟนตาซีพิกเซล"></canvas><button id="introMotion" class="intro-motion" aria-label="หยุดภาพเคลื่อนไหว" aria-pressed="true">❚❚</button><div class="start-world-caption"><button id="samplePrev" aria-label="ดูเผ่าตัวอย่างก่อนหน้า">←</button><div><small>ในโลกนี้ คุณอาจเป็น…</small><strong id="sampleRace"></strong><span id="sampleRealm"></span></div><button id="sampleNext" aria-label="ดูเผ่าตัวอย่างถัดไป">→</button></div><span class="sample-count" id="sampleNumber"></span></div><div class="start-counts"><span><b>${RACES.length}</b> เผ่าพันธุ์</span><span><b>${KINGDOMS.length}</b> อาณาจักร</span><span><b>${JOBS.length}</b> อาชีพ</span></div><div class="welcome-actions"><button class="primary" id="openBirth">✧ สุ่มชาติกำเนิดของฉัน</button>${resume?`<button class="secondary" id="resumeLife">▶ ใช้ชีวิตของ ${esc(state.name)} ต่อ</button>`:state.accepted===false&&state.birthRevealed?'<button class="secondary" id="reviewBirth">ดูชาติกำเนิดที่สุ่มไว้</button>':''}</div><small>โอกาสเกิดเป็นมนุษย์ 40% · เผ่าอื่นรวม 60%<br>ดูเผ่าพันธุ์ หน้าตา และครอบครัวก่อนเริ่ม<br>ยังไม่ถูกใจ? สุ่มเกิดใหม่ได้</small><div class="start-how"><span><b>01</b> สุ่มเกิด</span><span><b>02</b> รู้จักบ้านของคุณ</span><span><b>03</b> ใช้ชีวิตจนวันสุดท้าย</span></div><p class="start-note">${RACES.length} เผ่าพันธุ์ · ${KINGDOMS.length} อาณาจักร · ${JOBS.length} อาชีพ<br>${SceneCatalog.stats.scenes} ฉากใน ${SceneCatalog.stats.locations} สถานที่ · เลี้ยงสหายและแต่งบ้านของคุณ</p></section>`;
 $('#openBirth').onclick=()=>{if(resume&&!state.dead){modal('<h2>เริ่มสุ่มชีวิตใหม่?</h2><p>ชีวิตปัจจุบันจะถูกแทนที่เมื่อสุ่ม หากต้องการเก็บไว้ โปรดส่งออกเซฟก่อน</p><button class="primary" id="confirmRoll">เริ่มสุ่มชีวิตใหม่</button>');$('#confirmRoll').onclick=()=>{$('#modal').close();rollBirth()}}else rollBirth()};if($('#resumeLife'))$('#resumeLife').onclick=resumeLife;if($('#reviewBirth'))$('#reviewBirth').onclick=()=>{screen='birth';render()};
 $('#samplePrev').onclick=()=>{welcomeIndex=(welcomeIndex+welcomePeoples.length-1)%welcomePeoples.length;refreshWelcomeSample()};$('#sampleNext').onclick=()=>{welcomeIndex=(welcomeIndex+1)%welcomePeoples.length;refreshWelcomeSample()};
 const motion=$('#introMotion');const paint=()=>{motion.textContent=sceneMotion?'❚❚':'▶';motion.setAttribute('aria-pressed',String(sceneMotion));motion.setAttribute('aria-label',sceneMotion?'หยุดภาพเคลื่อนไหว':'เปิดภาพเคลื่อนไหว')};motion.onclick=()=>{sceneMotion=!sceneMotion;try{localStorage.setItem('aether-scene-motion',sceneMotion?'on':'off')}catch(e){}paint();drawIntroArt()};paint();refreshWelcomeSample()
}
function rollingPage(){app.innerHTML=`<section class="birth-stage"><div class="eyebrow">สุ่มเกิด</div><canvas id="rollPreview" class="rolling-preview" width="120" height="120" role="img" aria-label="ตัวอย่างเผ่าพันธุ์ที่กำลังสุ่ม" data-race="${state.race}" data-kingdom="${state.kingdom}"></canvas><h1>กำลังสุ่มชาติกำเนิด</h1><p>เผ่าพันธุ์ บ้านเกิด และคนที่จะเรียกคุณว่าครอบครัว</p><div class="rolling-window"><strong id="rollRace">${RACES[state.race][0]}</strong><span id="rollKingdom">${KINGDOMS[state.kingdom][0]}</span></div><div class="roll-dots"><i></i><i></i><i></i></div><p class="birth-fine">ยังไม่มีชีวิตใดเริ่มเดิน จนกว่าคุณจะเลือกเริ่ม</p></section>`;drawIntroArt()}
function rollBirth(){clearTimeout(birthTimer);const token=++birthToken;state=fresh();screen='rolling';clock.reset();render();let frame=0;const reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;const step=()=>{if(token!==birthToken)return;frame++;if($('#rollRace')){$('#rollRace').textContent=RACES[(state.race+frame*7)%RACES.length][0];$('#rollKingdom').textContent=KINGDOMS[(state.kingdom+frame*3)%KINGDOMS.length][0];const art=$('#rollPreview');if(art){art.dataset.race=(state.race+frame*7)%RACES.length;art.dataset.kingdom=(state.kingdom+frame*3)%KINGDOMS.length;art.setAttribute('aria-label','ตัวอย่างเผ่า'+$('#rollRace').textContent);drawIntroArt()}}if(frame<(reduce?1:16)){birthTimer=setTimeout(step,50+frame*9)}else{state.birthRevealed=true;screen='birth';save();render()}};birthTimer=setTimeout(step,reduce?20:80)}
function kinCards(s,full=false){const members=FamilyWorld.list(s),shown=full?members:members.slice(0,4);return `<div class="kin-grid">${shown.map(m=>`<article class="kin-card ${m.alive?'':'is-dead'}"><canvas width="32" height="72" data-kin="${esc(m.id)}" aria-label="ภาพพิกเซล ${esc(m.name)}"></canvas><div><strong>${esc(m.name)}</strong><small>${esc(m.role)} · ${m.alive?`อายุ ${FamilyWorld.age(s,m)} ปี`:`จากไปเมื่ออายุ ${m.deathAge??FamilyWorld.age(s,m)} ปี`}</small><small>${esc(m.occupation)}</small><small class="kin-trait">${esc(m.trait)}</small><span class="kin-trust">${m.alive?`ไว้ใจ ${Math.round(m.trust)}%`:`อยู่ในความทรงจำของบ้าน`}</span></div></article>`).join('')}</div>${!full&&members.length>shown.length?`<button class="kin-more" id="familyAll">สมาชิกในบ้านอีก ${members.length-shown.length} ${s.race===0?'คน':'สมาชิก'} ↗</button>`:''}`}
function drawKins(root=document){root.querySelectorAll('[data-kin]').forEach(c=>{const m=FamilyWorld.list(state).find(x=>x.id===c.dataset.kin);if(m)Illustration.drawKin(c,state,m)})}
function mapDetail(d){modal(`<div class="overline">WORLD ATLAS · ${esc(d.title)}</div><h2>${esc(d.name)}</h2><p>${esc(d.terrain)}</p><p>${esc(d.rumor)}</p><div class="atlas-detail"><strong>จุดสังเกต</strong><span>${esc(d.landmark)}</span><strong>ถิ่นสำคัญ</strong><span>${d.region.map(esc).join(' · ')}</span>${d.water?`<strong>แหล่งน้ำ</strong><span>${esc(d.water)}</span><strong>เส้นทาง</strong><span>${esc(d.connections)}</span>`:''}</div>`)}
function bindMap(root=document){WorldMap.bind(root,r=>RealmLife.get(r.index)?RealmUI.open(r.index):mapDetail(r))}
function activityPanel(s){const age=Engine.biological(s),c=Simulation.ensure(s),locked=s.dead||c.pending||s.outcome,used=c.actionQuarter===c.count;if(locked)return '';return `<section class="panel activity-panel"><div class="activity-intro"><span class="eyebrow">กิจกรรม</span><h2>ช่วงเวลาของคุณ</h2><p>${used?'คุณเลือกใช้เวลาช่วงนี้ไปแล้ว อีกไม่นานปฏิทินจะพาเรื่องราวต่อ':'เลือกลงมือเองได้หนึ่งอย่างในช่วงนี้ ชีวิตส่วนอื่นยังเดินต่อไปตามปกติ'}</p></div><div class="activity-options">${[['family','⌂',age<4?'อยู่ใกล้คนคุ้นเคย':'อยู่กับครอบครัว','เพิ่มความผูกพันและความสุข'],['explore','⌖',age<4?'มองโลกใกล้ตัว':age<13?'สำรวจใกล้บ้าน':'ออกสำรวจเมือง',age<4?'แสง สี และเสียงใหม่':'พบเส้นทางและเพิ่มปัญญา'],['practice','✧',age<4?'ลองขยับร่างกาย':'ฝึกสิ่งที่สนใจ',age<4?'ค่อย ๆ เรียนรู้ตามวัย':'พัฒนาทักษะที่เลือก'],['rest','☾','พักดูแลตัวเอง','ฟื้นแรงกายและใจ']].map(([id,icon,label,hint])=>`<button class="activity-choice" data-activity="${id}" ${used?'disabled':''}><span>${icon}</span><b>${label}</b><small>${hint}</small></button>`).join('')}</div></section>`}
function birthPage(){const s=state,r=RACES[s.race],k=KINGDOMS[s.kingdom],id=s.identity||{given:s.name.split(' ')[0],family:s.name.split(' ').slice(1).join(' ')};const home=FamilyWorld.primary(s),kin=FamilyWorld.list(s);app.innerHTML=`<section class="birth-intro"><h1>คุณจะเกิดเป็น…</h1><p>อ่านก่อนตัดสินใจ เวลาจะเริ่มเมื่อกดใช้ชีวิตชาตินี้</p></section><section class="birth-certificate panel"><div class="birth-topline"><span>บันทึกแห่งชาติกำเนิด</span><span>NO. ${s.seed.toString(16).toUpperCase()}</span></div><div class="birth-main"><figure class="birth-race-preview"><canvas id="birthPreview" width="120" height="120" role="img" aria-label="ตัวอย่างรูปลักษณ์เมื่อเติบโตของเผ่า${r[0]}"></canvas><figcaption><strong>${r[0]}</strong><span>ตัวอย่างรูปลักษณ์เมื่อเติบโต</span></figcaption></figure><div class="birth-identity"><span class="eyebrow">${s.race!==0?'นามที่'+esc(SpeciesSociety.profile(s).group)+'ใช้เรียก':'ชื่อที่ครอบครัวเลือกให้'}</span><h2>${esc(id.given)}</h2><h3>${esc(id.family)}</h3><p>${r[0]} · ${r[1]}</p><span class="badge">เกิดใน ${k[0]}</span></div></div>${TierUI.birth(s)}<div class="birth-facts"><div><small>ถิ่นกำเนิด</small><strong>${k[0]} · ${k[1]}</strong><p>${k[2]}</p></div><div><small>${esc(SpeciesSociety.heading(s))}</small><strong>${HumanOrigins.classLabel(s)}</strong><p>${esc(s.race!==0?SpeciesSociety.note(s):s.heritage?.note||s.family)}</p></div><div><small>${s.race===0?'สายเลือดและพรติดตัว':'รูปกำเนิดและพรติดตัว'}</small><strong>${r[0]}</strong><p>อายุขัยทั่วไปประมาณ ${r[2]} ปี · เวทกำเนิด +${r[4]}</p></div><div><small>ถิ่นที่คุณจะเติบโต</small><strong>${esc(SpeciesSociety.caregiver(s))} ${esc(home.name)}</strong><p>${esc(home.occupation)} · ${esc(home.trait)}</p></div></div>${HumanUI.birth(s)}${SocietyUI.birth(s)}${EcologyUI.birth(s)}<details class="birth-world-details"><summary>รู้จักสมาชิกในถิ่นและดูแผนที่เกิด ↗</summary><section class="panel household-card"><div class="section-title"><span>⌂ ${esc(SpeciesSociety.kinHeading(s))}</span><span>${kin.length} ${s.race===0?'คน':'สมาชิก'}</span></div><p class="household-intro">${esc(s.race!==0?SpeciesSociety.note(s):s.household.originNote)} · ${s.race===0?'บ้านสกุล ':''}${esc(s.household.surname)}</p>${kinCards(s,true)}</section><details class="panel map-card"><summary>ดูบ้านเกิดบนแผนที่</summary><div class="section-title"><span>⌖ จุดกำเนิดบนแผนที่</span><span>${k[0]}</span></div>${WorldMap.svg(s,{compact:true})}<p class="map-caption">ดาวสีทองคือบ้านเกิดของคุณ แผนที่แสดงอาณาจักรทั้ง ${KINGDOMS.length} แห่ง</p></details></details><div class="birth-prologue"><span>❦</span><p>${s.race!==0?esc(SpeciesSociety.prologue(s)):`ผู้ปกครอง ${esc(home.name)} อาศัยอยู่ใน${k[0]} และทำงานเป็น${esc(home.occupation)} ${kin.length>1?'ส่วน '+kin.slice(1,3).map(m=>esc(m.name)+' ผู้เป็น'+esc(m.role)).join(' และ '):''} คุณจะเติบโตท่ามกลางวิถีของ${r[0]}และข้อจำกัดเฉพาะของ${HumanOrigins.classLabel(s)} การตัดสินใจครั้งแรกจะมาถึงเมื่อคุณโตพอรับรู้ผลของมัน`}</p></div><div class="birth-actions"><button class="primary" id="acceptLife">ใช้ชีวิตชาตินี้ →</button><button class="secondary" id="rerollBirth">↻ สุ่มเกิดใหม่</button></div><p class="birth-fine">เวลายังหยุดอยู่ คุณเปลี่ยนชาติกำเนิดได้โดยไม่เสียเซฟชีวิตอื่นที่ส่งออกไว้</p></section>`;$('#acceptLife').onclick=()=>{Simulation.begin(state);clock.set({auto:false});screen='playing';tab='life';clock.reset();Simulation.nextQuarter(state);render()};$('#rerollBirth').onclick=rollBirth;drawIntroArt();drawKins();bindMap();TierUI.bind();$('#familyAll')?.addEventListener('click',familyDialog)}
function resumeLife(){Simulation.ensure(state);state.accepted=true;state.journey=null;if(state.outcome)state.outcome=null;screen='playing';tab='life';clock.reset();render()}
function life(){const s=state,r=RACES[s.race],k=KINGDOMS[s.kingdom],cal=Simulation.ensure(s);Narrative.ensure(s);const growth=LifeGrowth.ensure(s),work=Livelihood.ensure(s);const latest=s.diary.entries.find(e=>!e.legacyAgeMismatch&&!e.legacyEcologyMismatch),home=FamilyWorld.primary(s);app.innerHTML=`<section class="life-heading"><div><div class="eyebrow">ชีวิตนี้</div><div class="world-year-mark" aria-label="ปีปัจจุบัน"><span>ศักราชโลก</span><b>${WorldTimeline.year(s)}</b><span>เดือน ${cal.quarter*3+1}</span></div><h1>${esc(s.name)}</h1><p>${r[0]} · ${k[0]} · ${s.job===null?(typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s)?'ดำรงชีวิตตามถิ่นและร่าง':'ยังไม่มีงานประจำ'):JOBS[s.job][0]+' · '+Livelihood.levels[work.level]}</p>${TierUI.compact(s)}<p class="social-origin-line"><span class="badge">${esc(HumanOrigins.classLabel(s))}</span> · ${esc(s.race!==0?SpeciesSociety.local[s.race]:s.heritage?.note||s.household.originNote)}</p><p class="growth-line">${LifeGrowth.educationLabel(s,growth.education)}${work.business?' · กิจการ: '+Livelihood.businessCatalog.find(x=>x.id===work.business.id).name:''}</p></div><div class="age-display"><strong>${s.age}</strong><span>ปี</span><small>เดือน ${cal.quarter*3+1} · ${lifeStage()}</small></div></section><div class="quick-stats">${['health','joy','magic','bond'].map(key=>`<div><span>${labels[key]}</span><b>${Math.round(s[key])}</b><i style="--value:${Math.max(0,Math.min(100,s[key]))}%"></i></div>`).join('')}</div><div class="quick-links"><button id="familyOverview">${s.race!==0?esc(SpeciesSociety.profile(s).group):'ครอบครัว'} ${s.household.members.length} ${s.race===0?'คน':'สมาชิก'}</button><button id="atlasOverview">แผนที่ · ${k[0]}</button><button id="lifeInfo">สถานะทั้งหมด ↓</button><button class="money-quick" id="spendMoney">${RaceDrives.cashless(s)?'⌁ '+esc(SpeciesSociety.profile(s).res)+' '+Math.round(s.raceDrives.resource)+'/100':'◈ '+Math.floor(s.gold)+' ทอง · ใช้เงิน'}</button></div>${clockMarkup()}${LifeHazardUI.panel(s)}${HumanUI.panel(s)}${LifeUI.panel(s)}${EcologyUI.panel(s)}${LifeProjectUI.panel(s)}<div class="life-layout"><aside class="life-sidebar"><section class="panel profile"><canvas class="portrait" width="180" height="150" id="portrait" aria-label="ภาพพิกเซลของคุณกับครอบครัว"></canvas><span class="badge">${r[1]}</span><div class="side-summary"><span>◈ ${Math.round(s.gold*100)/100} ทอง</span><span>✦ ชื่อเสียง ${Math.round(s.fame)}</span></div></section><section class="panel household-panel"><h3 class="section-title"><span>${s.race!==0?esc(SpeciesSociety.profile(s).group):'ครอบครัว'} · ${esc(s.household.surname)}</span><span>${s.household.members.length} ${s.race===0?'คน':'สมาชิก'}</span></h3><p class="household-note">${esc(s.race!==0?SpeciesSociety.note(s):s.household.originNote)} · บ้านของ${esc(home.name)}</p>${kinCards(s,false)}</section><section class="panel stats"><h3 class="section-title">สถานะ</h3>${['health','joy','power','magic','wisdom','bond','fame'].map(x=>`<div class="stat"><div class="stat-label"><span>${labels[x]}</span><span>${Math.round(s[x])}</span></div><div class="bar"><i style="width:${s[x]}%"></i></div></div>`).join('')}</section><details class="panel origin-details"><summary>ชาติกำเนิดและครอบครัว</summary><p>${HumanOrigins.classLabel(s)} · ${esc(s.family)}</p><p>เกิดใน ${KINGDOMS[s.homeKingdom??s.kingdom][0]} · ปัจจุบันอยู่ ${k[0]}</p><p>${s.partner?'คู่ชีวิต: '+esc(s.partner):'ยังไม่มีคู่ชีวิต'}${s.children?' · ลูก '+s.children+' คน':''}</p>${s.pet?`<p>สัตว์เลี้ยง: ${esc(s.pet.name)} · ผูกพัน ${s.pet.bond}%</p><button class="secondary" id="petcare">ดูแลสหาย</button>`:''}</details>${peoplePanel(s)}<div class="world-note">ข่าวนอกเมือง<small>${esc(WorldRelations.summary(s)[0]?.title||k[3])}</small><button class="world-news-link" id="openRelations">ดูความสัมพันธ์ระหว่างเผ่า →</button></div></aside><section class="life-reading"><div class="scene panel"><canvas id="scene" width="480" height="180" aria-label="ฉากพิกเซลแอนิเมชันตามสถานการณ์ชีวิต"></canvas><button id="sceneMotion" class="scene-motion" aria-label="เปิดหรือหยุดแอนิเมชันฉาก"></button><span class="scene-caption">⌖ ${esc(SceneCatalog.resolve(s).label)} · ${esc(SceneCatalog.resolve(s).phase)}</span></div>${s.dead?`<article class="panel">${ending()}</article>`:cal.pending?decisionCard(s):s.outcome?`<article class="decision-result panel ${s.outcome.success===false?'tone-loss':''}"><span class="eyebrow">ผลการตัดสินใจ</span><h2>${esc(s.outcome.choice)}</h2><p>${esc(StoryPresentation.short(s.outcome.text,180))}</p>${outcomeEffects(s)}<small>ผลของการเลือกถูกเก็บไว้ในสมุดชีวิตแล้ว</small><button class="secondary acknowledge-outcome" id="acknowledgeOutcome">รับรู้แล้ว · วางแผนช่วงถัดไป →</button></article>`:`<div class="life-now"><span class="live-dot"></span> ชีวิตกำลังดำเนินไป <span>เมื่อถึงเหตุการณ์สำคัญ เวลาจะหยุดรอคุณ</span></div>`}${RealmUI.panel(s)}${AdventureUI.panel(s)}${HousingUI.panel(s)}${BeliefUI.panel(s)}${EpochUI.panel(s)}${BondsUI.panel(s)}${activityPanel(s)}<details class="panel map-preview"><summary>แผนที่และเส้นทางของคุณ</summary><div class="map-preview-heading"><div><span class="eyebrow">ตำแหน่งปัจจุบัน</span><h2>${k[0]} · ${k[1]}</h2><p>เกิดที่ ${KINGDOMS[s.homeKingdom??s.kingdom][0]}${s.route?.length>1?' · เคยไป '+(s.route.length-1)+' อาณาจักร':''}</p></div><button class="secondary" id="openAtlas">เปิดแผนที่ใหญ่ ↗</button></div>${WorldMap.svg(s,{compact:true})}<p class="map-caption">ดาวทองคือจุดกำเนิด หมุดสว่างคือที่อยู่ล่าสุด เส้นประแสดงเส้นทางที่เดินทาง</p></details><section class="panel life-feed"><div class="feed-heading"><div><span class="eyebrow">บันทึกชีวิต</span><h2>เรื่องราวระหว่างทาง</h2></div><button id="diaryAll">เปิดสมุดทั้งเล่ม ↗</button></div>${s.diary.entries.some(e=>e.legacyAgeMismatch||e.legacyEcologyMismatch)?'<p class="legacy-age-note">บันทึกจากกติกาเดิมเก็บไว้ในสมุดทั้งเล่ม</p>':''}<div class="event-feed" aria-label="เหตุการณ์ที่เกิดขึ้นในชีวิต">${s.diary.entries.filter(e=>!e.legacyAgeMismatch&&!e.legacyEcologyMismatch).slice(0,feedLimit).map((e,i)=>`<article class="feed-moment tone-${StoryPresentation.tone(e)} ${i===0?'newest':''}"><div class="feed-date"><b>${e.age}</b><span>ปี</span><small>เดือน ${e.month||1}</small></div><div class="feed-content"><div class="feed-kind">${StoryPresentation.label(e)?'':(e.kind==='loss'?'การสูญเสีย':e.kind==='spending'?'การใช้เงิน':e.kind==='investment'?'เงินลงทุน':e.kind==='world'?'ข่าวระหว่างเผ่า':e.kind==='growth'?'การเติบโต':e.kind==='story'?'เรื่องราวต่อเนื่อง':e.kind==='work'?'งานและกิจการ':e.kind==='automatic'?'ชีวิตประจำวัน':e.kind==='interaction'?'ความสัมพันธ์':e.kind==='decision'?'การตัดสินใจ':e.kind==='family'?'ครอบครัว':e.kind==='memory'?'ความทรงจำ':'ช่วงหนึ่งของชีวิต')+ ' · '}${esc(e.phase)}</div>${StoryPresentation.label(e)?`<span class="moment-label">${StoryPresentation.label(e)}</span>`:''}<h3>${esc(e.title)}</h3><p class="moment-brief">${esc(StoryPresentation.summary(e))}</p>${e.change?`<small class="effect-tag ${e.change.value<0?'effect-loss':''}">${labels[e.change.stat]||'ทอง'} ${e.change.value>0?'+':''}${e.change.value}</small>`:''}<button class="read-moment" data-entry="${e.id}">อ่านหน้านี้ ↗</button></div></article>`).join('')||'<div class="empty">กำลังเริ่มบันทึกวันแรกของชีวิตคุณ</div>'}</div>${s.diary.entries.filter(e=>!e.legacyAgeMismatch&&!e.legacyEcologyMismatch).length>feedLimit?'<button class="secondary" id="olderLife" style="width:100%">อ่านชีวิตก่อนหน้านี้อีก 30 เรื่อง ↓</button>':'<p class="journal-help">ถึงหน้าแรกที่ยังเก็บไว้ของชีวิตนี้แล้ว</p>'}</section><div class="toolbar"><button id="peopleMenu">♡ ผู้คน</button><button id="career">⚒ อาชีพ / กิจการ</button><button id="travel">⌁ เดินทาง</button><button id="focus">✧ โฟกัสรายปี</button><button id="petMenu">♧ สัตว์เลี้ยง</button><button id="homeShop">⌂ ของใช้ / งานอดิเรก</button><button id="export">↓ ส่งออกเซฟ</button><button id="import">↑ นำเข้าเซฟ</button><button id="restart">↻ ชีวิตใหม่</button></div><input class="import" type="file" accept="application/json,.json" id="file"><button id="alllog" class="secondary" style="width:100%">ดูบันทึกเหตุการณ์สำคัญทั้งหมด</button></section></div>`;drawPortrait();drawScene();drawKins();bindMap();bindLife();bindClock();bindNarrative();LifeUI.bind();LifeProjectUI.bind();SpendingUI.bind();RealmUI.bind();BondsUI.bind();HumanUI.bind();EcologyUI.bind();EpochUI.bind();BeliefUI.bind();if(s.dead)LegacyUI.bind(document,s);DecisionPopup.bind();$('#openRelations').onclick=()=>{tab='world';worldType='relations';render()};$('#familyOverview').onclick=familyDialog;$('#atlasOverview').onclick=()=>{tab='world';worldType='map';render()};$('#lifeInfo').onclick=()=>document.querySelector('.life-sidebar').scrollIntoView({behavior:'smooth',block:'start'});$('#openAtlas')?.addEventListener('click',()=>{tab='world';worldType='map';render()});document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{if(Simulation.activity(state,b.dataset.activity)){clock.reset();render();toast('บันทึกช่วงเวลานี้ไว้ในชีวิตแล้ว')}});save();DecisionPopup.sync()}
function decisionCard(s){return `<article class="panel decision-preview"><small>✦ จุดเปลี่ยนของชีวิต · รอคำตอบของคุณ</small><h2>${ctx(s.event.title)}</h2><p>${esc(StoryPresentation.short(WorldLore.fill(s,s.event.text,s.event.context),130))}</p><button id="reviewDecision" class="secondary">เปิดหน้าต่างตัดสินใจ →</button></article>`}
function livingPage(s){const e=s.diary.entries[0];return e?`<div class="living-page"><div class="diary-dateline">${esc(e.phase)} · ${esc(e.season)} · อายุ ${e.age} ปี</div>${e.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="needs-row"><span>แรงกาย ${s.diary.energy}/100</span><span>ความอุ่นใจ ${s.diary.comfort}/100</span><span>ได้ใช้เวลากับคนอื่น ${s.diary.social}/100</span></div></div>`:''}
function journalPanel(s){const d=Narrative.ensure(s);return `<section class="panel journal"><h3 class="section-title"><span>❦ สมุดชีวิตของ ${esc(s.name.split(' ')[0])}</span><button id="diaryAll">อ่านทุกหน้าที่เก็บไว้ ↗</button></h3><p class="journal-help">${s.dead?'เรื่องเล่าที่เดินทางมาด้วยกัน':s.journey?'เรื่องราวใหม่จะค่อย ๆ ปรากฏระหว่างที่ชีวิตดำเนินไป':'แม้ในวันที่ต้องตัดสินใจ ชีวิตก็มีเรื่องเล่าระหว่างทาง'}</p><div class="journal-list">${d.entries.slice(s.journey?1:0,s.journey?4:3).map(e=>`<button class="journal-entry" data-entry="${e.id}"><small>อายุ ${e.age} ปี · ${esc(e.phase)} · ${esc(e.season)}</small><strong>${esc(e.title)}</strong><span>${esc(e.paragraphs[0])}</span></button>`).join('')||'<p class="journal-help">นี่คือหน้าแรก เรื่องราวถัดไปกำลังเริ่มต้น</p>'}</div></section>`}
function peoplePanel(s){const all=LifeBonds.list(s),shown=[...all.filter(p=>p.alive),...all.filter(p=>!p.alive)].slice(0,5);return `<section class="panel side people-panel"><h3 class="section-title">คนใกล้ตัว <button id="peopleAll" style="font-size:10px">สมุดคนสำคัญ ↗</button></h3>${shown.map(p=>`<div class="person-line"><b>${esc(p.name)}</b><small>${esc(p.role.split(' · ')[0])}${p.alive?' · ไว้ใจ '+Math.round(p.trust)+'%':' · ในความทรงจำ'}</small></div>`).join('')}<p class="journal-help">${shown.some(p=>p.promise?.state==='pending')?'ยังมีคำสัญญาที่ใครบางคนรอคุณอยู่':'ความฝันและช่วงเวลาที่เคยมีให้กันเก็บอยู่ในสมุดคนสำคัญ'}</p></section>`}

function familyDialog(){const members=FamilyWorld.list(state);modal(`<div class="overline">${state.race===0?'YOUR HOUSEHOLD':esc(SpeciesSociety.profile(state).group)} · ${esc(state.household.surname)}</div><h2>${state.race!==0?esc(SpeciesSociety.kinHeading(state)):'คนที่ร่วมสร้างบ้านหลังนี้'}</h2><p>${esc(state.race!==0?SpeciesSociety.note(state):state.household.originNote)} · ${state.race===0?'บ้านสกุล':''} ${esc(state.household.surname)} มีคน ${members.length} คน แต่ละคนมีอาชีพ ความทรงจำ และความสัมพันธ์กับคุณ</p><div class="family-dialog-grid">${members.map(m=>`<article class="family-person ${m.alive?'':'is-dead'}"><canvas width="40" height="78" data-kin="${esc(m.id)}"></canvas><div><h3>${esc(m.name)}</h3><small>${esc(m.role)} · ${m.alive?`อายุ ${FamilyWorld.age(state,m)} ปี`:`เสียชีวิตเมื่ออายุ ${m.deathAge??FamilyWorld.age(state,m)} ปี`}</small><p>${esc(m.occupation)} · ${esc(m.trait)}</p><span>${m.alive?`ไว้ใจ ${Math.round(m.trust)}%`:`อยู่ในความทรงจำ`}</span></div></article>`).join('')}</div>`);drawKins($('#modalBody'))}
function bindNarrative(){if($('#olderLife'))$('#olderLife').onclick=()=>{const y=window.scrollY;feedLimit+=30;render();window.scrollTo(0,y)};if($('#diaryAll'))$('#diaryAll').onclick=()=>StoryJournal.open();document.querySelectorAll('[data-entry]').forEach(b=>b.onclick=()=>StoryJournal.entry(+b.dataset.entry));if($('#peopleAll'))$('#peopleAll').onclick=peopleDialog;if($('#peopleMenu'))$('#peopleMenu').onclick=peopleDialog;if($('#familyAll'))$('#familyAll').onclick=familyDialog}
function peopleDialog(){BondsUI.open()}

function ending(){return LegacyUI.markup(state)}
function record(){if(!state.dead||archive.some(a=>a.seed===state.seed))return;archive.unshift(JSON.parse(JSON.stringify(state)));archive=archive.slice(0,50);save()}
function bindLife(){TierUI.bind();AdventureUI.bind();HousingUI.bind();if($('#acknowledgeOutcome'))$('#acknowledgeOutcome').onclick=()=>{if(state.outcome&&!state.calendar?.pending&&!state.dead){state.outcome=null;save();clock.reset();render()}};document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(Simulation.choose(state,Number(b.dataset.choice))){record();clock.reset();render()}});if($('#next'))$('#next').onclick=()=>{Engine.advance(state);record();render()};$('#career').onclick=careers;$('#travel').onclick=travel;$('#focus').onclick=focus;$('#petMenu').onclick=()=>LifeUI.companions();$('#homeShop').onclick=()=>LifeUI.shop();$('#export').onclick=exportSave;$('#import').onclick=()=>$('#file').click();$('#file').onchange=importSave;$('#restart').onclick=()=>newLife(false);if($('#reborn'))$('#reborn').onclick=()=>newLife(true);if($('#share'))$('#share').onclick=share;$('#alllog').onclick=()=>modal(`<div class="overline">CHRONICLE</div><h2>บันทึกของ ${esc(state.name)}</h2>${state.log.map(l=>`<div class="log"><strong>อายุ ${l.age} ปี</strong>${esc(l.text)}</div>`).join('')}`);if($('#petcare'))$('#petcare').onclick=petcare}
function newLife(now){if(now){screen='welcome';tab='life';render();return}modal('<h2>เปิดชีวิตใหม่?</h2><p>สุ่มชาติกำเนิดใหม่จะแทนชีวิตปัจจุบัน โปรดส่งออกเซฟก่อนหากต้องการเก็บไว้</p><button class="primary" id="confirmNew">ไปสุ่มชาติกำเนิดใหม่</button>');$('#confirmNew').onclick=()=>{$('#modal').close();rollBirth()}}
function careers(pathId=null){
 const l=Livelihood.ensure(state),age=Engine.biological(state);modal(`<div class="overline">อาชีพและการฝึกฝน</div><h2>${state.job===null?'เลือกเส้นทางงาน':esc(JOBS[state.job][0])}</h2><p>${state.job===null?'เริ่มงานได้เมื่อถึงวัยทำงาน และมีทักษะตามที่งานต้องการ':`${Livelihood.levels[l.level]} · ประสบการณ์ ${l.tenure.toFixed(1)} ปีเทียบอายุมนุษย์ · ความชำนาญ ${Math.round(l.proficiency)}/100`}<br>เวลางาน ${Math.round((l.workload??1)*100)}% · การศึกษา: ${LifeGrowth.educationLabel(state)} · เงิน ${state.gold.toFixed(2)} ทอง<br>ปี ${WorldTimeline.year(state)}: รับสุทธิสะสม ${Economy.annual(state).income.toFixed(2)} · ภาระและใช้จ่ายสะสม ${Economy.annual(state).cost.toFixed(2)} ทอง</p><div class="tabs work-tabs"><button class="active">อาชีพ ${JOBS.length} แบบ</button><button id="openBusinesses">กิจการ ${Livelihood.businessCatalog.length} แบบ →</button>${state.job!==null&&age>=18?`<button id="workHours">${l.workload===1?'ลดเวลางานเหลือ 60%':'กลับมาทำงานเต็มเวลา'}</button>`:''}</div><p class="journal-help">งานระดับสูงต้องมีวัย ประสบการณ์พื้นฐาน หรือชื่อเสียงเหมาะสม เปลี่ยนสายงานแล้วเริ่มสะสมความชำนาญในงานใหม่</p><input id="jobSearch" class="job-search" type="search" placeholder="ค้นหาอาชีพ เช่น ช่าง ครู ผู้รักษา" aria-label="ค้นหาอาชีพ"><div class="choices job-list">${JOBS.map((j,i)=>`<button class="choice" data-job="${i}" data-job-name="${esc(j[0])}" ${state.calendar?.pending||state.outcome||!Livelihood.canCareer(state,i)||state.job===i?'disabled':''}><span class="num">${state.job===i?'✓':String(i+1).padStart(2,'0')}</span><span><b>${esc(j[0])}</b><small>${labels[j[1]]} ${j[2]} · ${Adventures.isCareer({...state,job:i})?'รายได้ตามสัญญาที่ส่งสำเร็จ':'ฐานค่าจ้าง '+j[3].toLocaleString('en-US')+' ทองต่อปี'}${age<16?' · ยังไม่ถึงวัยทำงาน':!Livelihood.canCareer(state,i)?' · คุณสมบัติยังไม่ครบ':''}</small></span></button>`).join('')}</div>`);$('#openBusinesses').onclick=businesses;if($('#workHours'))$('#workHours').onclick=()=>{l.workload=l.workload===1?.6:1;save();careers()};$('#jobSearch').oninput=e=>document.querySelectorAll('[data-job]').forEach(b=>b.hidden=!GameLanguage.search(b.dataset.jobName,e.target.value));if(typeof pathId==='string'&&HumanOrigins.path(pathId)){const pattern=new RegExp(HumanOrigins.path(pathId).pattern);document.querySelectorAll('[data-job]').forEach(b=>b.hidden=!pattern.test(b.dataset.jobName));$('#jobSearch').placeholder='แสดงงานเส้นทาง '+HumanOrigins.path(pathId).name;const all=document.createElement('button');all.id='jobAll';all.className='secondary';all.textContent='แสดงทุกอาชีพ';all.onclick=()=>{$('#jobSearch').value='';$('#jobSearch').placeholder='ค้นหาอาชีพ';document.querySelectorAll('[data-job]').forEach(b=>b.hidden=false);all.remove()};$('#jobSearch').after(all)}document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{if(Engine.career(state,+b.dataset.job)){$('#modal').close();render();toast('เริ่มเส้นทางอาชีพใหม่แล้ว')}})
}
function businesses(){
 const l=Livelihood.ensure(state),b=l.business,age=Engine.biological(state),locked=state.dead||l.lastActionQuarter===(state.calendar?.count??0);const def=b?Livelihood.businessCatalog.find(x=>x.id===b.id):null;
 modal(`<div class="overline">กิจการของคุณ</div><h2>${def?esc(def.name):'เริ่มกิจการเล็ก ๆ'}</h2><p>เงินส่วนตัว ${state.gold.toFixed(2)} ทอง · ${b?'ร้านตั้งอยู่ใน'+KINGDOMS[b.kingdom][0]:'เริ่มได้เมื่อวัยเทียบมนุษย์ 18 ปี มีทักษะและเงินลงทุนเพียงพอ'}</p><div class="tabs"><button id="backToCareers">← อาชีพ</button></div>${b?`<div class="business-ledger"><div><span>ทุนหมุนเวียน</span><b>${b.cash.toFixed(2)}</b></div><div><span>รายรับช่วงล่าสุด</span><b>+${b.lastRevenue.toFixed(2)}</b></div><div><span>ต้นทุนช่วงล่าสุด</span><b>−${b.lastCosts.toFixed(2)}</b></div><div><span>กำไร / ขาดทุน</span><b class="${b.lastProfit<0?'loss':''}">${b.lastProfit>0?'+':''}${b.lastProfit.toFixed(2)}</b></div><div><span>คุณภาพ</span><b>${Math.round(b.quality)}/100</b></div><div><span>ลูกค้าประจำ</span><b>${Math.round(b.loyalty)}/100</b></div><div><span>ผู้ช่วย</span><b>${b.staff} คน</b></div><div><span>เบิกกำไรสะสม</span><b>${b.ownerDraw.toFixed(2)}</b></div></div><p class="journal-help">รายรับขึ้นกับฤดูกาล ทำเล ทักษะ คุณภาพ และคนซื้อสินค้า ค่าแรงผู้ช่วยเป็นต้นทุนประจำ บัญชีเดินต่ออัตโนมัติเมื่อเวลาผ่านไป</p><div class="choices">${[['quality','ปรับปรุงคุณภาพ',1200],['marketing','แนะนำร้านให้ชุมชนรู้จัก',800],['train',b.staff<3?'จ้างและฝึกผู้ช่วย':'ฝึกผู้ช่วยเพิ่มเติม',1500],['reserve','เติมทุนหมุนเวียน',1000],['close','เลิกกิจการและขายอุปกรณ์',0]].map(([id,label,cost])=>`<button class="choice" data-business-action="${id}" ${locked||state.gold<cost?'disabled':''}><b>${label}</b><small>${cost?cost+' ทอง':'รับคืนเงินหมุนเวียนและมูลค่าอุปกรณ์บางส่วน'}</small></button>`).join('')}</div><p class="journal-help">${locked?'คุณจัดการกิจการในช่วงนี้แล้ว รอช่วงเวลาถัดไป':'เลือกจัดการได้หนึ่งครั้งต่อช่วงเวลา'}</p>`:`<div class="choices">${Livelihood.businessCatalog.map(d=>`<button class="choice" data-business-open="${d.id}" ${state.dead||!Ecology.businessAllowed(state,d)||age<18||state.gold<d.cost||state[d.stat]<d.minimum?'disabled':''}><span><b>${esc(d.name)} · ทุน ${d.cost} ทอง</b><small>${esc(d.description)}<br>ต้องการ${labels[d.stat]} ${d.minimum} · ทำเลมีผลต่อยอดขาย</small></span></button>`).join('')}</div><p class="journal-help">เงินลงทุนบางส่วนใช้กับอุปกรณ์ ที่เหลือเก็บเป็นทุนหมุนเวียน กิจการมีโอกาสขาดทุนและต้องปิดได้</p>`}${l.history.length?`<details class="work-history"><summary>ประวัติงานและกิจการ</summary>${l.history.slice(0,12).map(e=>`<p>อายุ ${e.age} ปี · ${esc(e.text)}</p>`).join('')}</details>`:''}`);
 $('#backToCareers').onclick=careers;document.querySelectorAll('[data-business-open]').forEach(button=>button.onclick=()=>{const id=button.dataset.businessOpen;if(Livelihood.open(state,id)){const def=Livelihood.businessCatalog.find(x=>x.id===id);Narrative.append(state,{title:'เริ่ม'+def.name,kind:'work',key:'business-open-'+id+'-'+state.calendar.count,paragraphs:[`คุณนำเงิน ${def.cost} ทองมาลงทุนเปิด${def.name}ใน${KINGDOMS[state.kingdom][0]} โดยกันเงินส่วนหนึ่งไว้เป็นทุนหมุนเวียน`,def.description+' คุณจะเริ่มเห็นรายรับและต้นทุนเมื่อผ่านช่วงเวลาถัดไป']});save();businesses()}});document.querySelectorAll('[data-business-action]').forEach(button=>button.onclick=()=>{if(Livelihood.manage(state,button.dataset.businessAction)){save();businesses()}})
}

function travel(){modal(`<div class="overline">BEYOND THE HORIZON</div><h2>เดินทางสู่อาณาจักรใหม่</h2><p>ค่าเดินทางตามระยะและวิกฤต เริ่มที่ 350 ทอง · เริ่มย้ายถิ่นเมื่อถึงวัยทำงาน${state.calendar?.pending||state.outcome?' · ตอบเหตุการณ์และอ่านผลให้จบก่อนเดินทาง':''}</p><div class="choices">${KINGDOMS.map((k,i)=>`<button class="choice" data-travel="${i}" ${state.dead||state.calendar?.pending||state.outcome||state.gold<Economy.travelCost(state,i)||!Ecology.canTravel(state,i)||i===state.kingdom||Engine.biological(state)<16?'disabled':''}><span>⌖</span><span><b>${k[0]} ${state.kingdom===i?'· คุณอยู่ที่นี่':''}</b><small>${Economy.travelCost(state,i).toLocaleString('en-US')} ทอง · ${k[2]}${!Ecology.canTravel(state,i)?' · ไม่มีถิ่นพักที่รองรับร่างของคุณ':''}</small></span></button>`).join('')}</div>`);document.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>{if(Engine.travel(state,+b.dataset.travel)){$('#modal').close();render();toast('มาถึง'+KINGDOMS[state.kingdom][0]+'แล้ว')}})}
function focus(){LifeUI.focus()}
function petcare(){LifeUI.companions()}
function outcomeEffects(s){const names={...labels,gold:'ทอง',rank:'ชนชั้น',standing:'สถานะในชนชั้น',localTrust:'ความไว้ใจชุมชน',humanRelations:'สัมพันธ์กับมนุษย์',renown:'เกียรติยศ',clanFavor:'ความไว้ใจของตระกูล',driveResource:'แหล่งดำรงชีวิต'};return s.outcome?.effects?.length?`<div class="outcome-effects">${s.outcome.effects.map(e=>`<span class="effect-tag ${e.delta<0?'effect-loss':''}">${names[e.key]||esc(e.key)} ${e.delta>0?'+':''}${e.delta.toFixed(1).replace(/\.0$/,'')}</span>`).join('')}</div>`:''}
function exportSave(){const blob=new Blob([JSON.stringify({format:'aether-v1',life:state,archive,playback:clock.prefs},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fantasy-life-'+state.seed+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('ส่งออกบันทึกแล้ว')}
async function importSave(e){const file=e.target.files[0];if(!file)return;if(file.size>64*1024*1024){toast('ไฟล์ใหญ่เกินไป');return}try{const data=JSON.parse(await file.text());if(data.format!=='aether-v1'||!Array.isArray(data.archive)||data.archive.length>50)throw Error();const imported=Engine.hydrate(data.life);const history=data.archive.map(Engine.hydrate);modal('<h2>นำเข้าบันทึกชีวิต?</h2><p>ข้อมูลในไฟล์จะมาแทนชีวิตและหอจดหมายเหตุในเบราว์เซอร์นี้</p><button class="primary" id="confirmImport">นำเข้าและใช้บันทึกนี้</button>');$('#confirmImport').onclick=()=>{state=imported;archive=history;clock.reset();$('#modal').close();screen='playing';Simulation.ensure(state);state.accepted=true;tab='life';if(data.playback)clock.set(data.playback);render();toast('นำเข้าบันทึกสำเร็จ')}}catch(err){toast('ไฟล์บันทึกไม่ถูกต้องหรือเวอร์ชันไม่รองรับ')}e.target.value=''}
async function share(){const r=LifeLegacy.summary(state);const text=GameLanguage.text(`1 in 10 Billion: Fantasy\n${state.name} · ${RACES[state.race][0]}\n${r.title} · ใช้ชีวิต ${state.age} ปี\n${r.milestones[0]?.title||state.ending}\n${location.origin}`);try{if(navigator.share)await navigator.share({title:GameLanguage.text('ตำนานชีวิตของฉัน'),text});else{await navigator.clipboard.writeText(text);toast('คัดลอกตำนานแล้ว')}}catch(e){toast('ยังไม่ได้แบ่งปัน ลองอีกครั้งได้')}}
function world(){const types=[['map','แผนที่โลก · '+KINGDOMS.length+' อาณาจักร'],['relations','ความสัมพันธ์ระหว่างเผ่า'],['clan',HumanOrigins.clans.length+' ตระกูลมนุษย์'],['race','เผ่าพันธุ์ · '+RACES.length],['kingdom','อาณาจักร · '+KINGDOMS.length],['job','อาชีพ · '+JOBS.length],['pet','สัตว์เลี้ยง · '+PETS.length]];const content=worldType==='clan'?HumanUI.catalog(state):worldType==='relations'?WorldRelations.markup(state):worldType==='map'?`<section class="atlas-page panel"><div class="atlas-heading"><div><div class="overline">แผนที่โลก</div><h2>แผ่นดินที่เรื่องราวของคุณเกิดขึ้น</h2><p>เลือกอาณาจักรบนแผนที่เพื่ออ่านภูมิประเทศ ข่าวล่าสุด และสถานที่สำคัญ</p></div><div class="map-key"><span>✦ จุดกำเนิด ${KINGDOMS[state.homeKingdom??state.kingdom][0]}</span><span>● ปัจจุบัน ${KINGDOMS[state.kingdom][0]}</span></div></div>${WorldMap.svg(state)}<div class="atlas-summary"><strong>อาณาจักรปัจจุบัน: ${KINGDOMS[state.kingdom][0]}</strong><span>${KINGDOMS[state.kingdom][2]} · ${KINGDOMS[state.kingdom][3]}</span></div><div class="atlas-dossiers">${KINGDOMS.map((k,i)=>`<button class="atlas-dossier ${i===state.kingdom?'active':''}" data-map-region="${i}"><small>REALM ${String(i+1).padStart(2,'0')}</small><strong>${k[0]}</strong><span>${k[2]}</span></button>`).join('')}</div></section>`:`<div class="world-search"><input id="worldSearch" type="search" aria-label="ค้นหาในสารานุกรมโลก" placeholder="ค้นหาชื่อหรือเรื่องที่สนใจ…"><span id="worldFound"></span></div><div class="grid world-catalog-cards">${(worldType==='race'?RACES:worldType==='kingdom'?KINGDOMS:worldType==='job'?JOBS:PETS).map((x,i)=>`<article class="panel card" data-world-card>${worldType==='race'?`<canvas class="world-portrait" width="120" height="120" data-world-race="${i}" aria-label="ภาพตัวอย่าง ${esc(x[0])}"></canvas>`:''}<div class="overline">${worldType==='race'?Species.label(i):worldType==='kingdom'?'KINGDOM':worldType==='job'?'CALLING':'COMPANION'} ${String(i+1).padStart(2,'0')}</div><h3>${worldType==='pet'?x:x[0]}</h3><p>${worldType==='race'?`${x[1]}<br>โอกาสสุ่มเกิด ${i===0?'40':(60/(RACES.length-1)).toFixed(2)}%<br>อายุขัยทั่วไป ${x[2]} ปี · วัยผู้ใหญ่ ${Species.maturity(i)} ปี<br>พลังเวทกำเนิด +${x[4]}<br>${Ecology.profile(i).label}<br>${Ecology.profile(i).learningSkill}<br>${WorldLore.raceWays[i][0]}<br>ชาติกำเนิดนี้จะเปลี่ยนธรรมเนียม เหตุการณ์ และรูปแบบฉาก` :worldType==='kingdom'?`${x[1]}<br>${x[2]}<br>${x[3]}<br>สถานที่: ${WorldLore.places[i].join(' · ')}`:worldType==='job'?`คุณสมบัติ: ${labels[x[1]]} ${x[2]}<br>ค่าจ้างพื้นฐาน ${x[3]} ทองต่อปีเทียบอายุมนุษย์`:'พบได้ในเหตุการณ์ระหว่างทาง สร้างความไว้ใจด้วยอาหารและการผจญภัยร่วมกัน'}</p></article>`).join('')}</div>`;app.innerHTML=`<div class="tabs atlas-tabs">${types.map(([k,v])=>`<button data-world="${k}" class="${worldType===k?'active':''}">${v}</button>`).join('')}</div>${content}`;document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{worldType=b.dataset.world;world()});bindMap();HumanUI.bindCatalog();const search=$('#worldSearch');if(search){const cards=[...document.querySelectorAll('[data-world-card]')];const filter=()=>{let count=0;const term=search.value.trim().toLocaleLowerCase('th');for(const c of cards){c.hidden=!c.textContent.toLocaleLowerCase('th').includes(term);if(!c.hidden)count++}$('#worldFound').textContent=count+' รายการ'};search.oninput=filter;filter();document.querySelectorAll('[data-world-race]').forEach(c=>Illustration.drawRacePreview(c,{race:+c.dataset.worldRace,kingdom:state.kingdom,seed:17017,rank:1,look:{hair:(+c.dataset.worldRace)%5,coat:(+c.dataset.worldRace)%6,eyes:0}},0))}}
function archives(){app.innerHTML=`<div class="section-title"><div><div class="overline">THE HALL OF REMEMBRANCE</div><h2 style="font-weight:500">เรื่องเล่าที่ไม่เลือนหาย</h2></div><span>${archive.length} / 50 ชีวิต</span></div>${archive.length?`<div class="grid">${archive.map((s,i)=>`<article class="panel card"><div class="overline">LIFE ${archive.length-i} · ${s.age} YEARS</div><h3>${esc(s.name)}</h3><span class="badge">${RACES[s.race][0]}</span><p>${esc(s.ending)}<br>${s.turn} การตัดสินใจ · ${LifeLegacy.summary(s).worlds.length} อาณาจักรในเรื่องราว</p><button class="secondary" data-memory="${i}">เปิดบันทึกชีวิต ↗</button></article>`).join('')}</div>`:'<div class="panel empty"><div style="font-size:42px;color:var(--gold)">❦</div><h3>ยังไม่มีหน้าหนังสือที่ปิดลง</h3><p style="color:var(--muted)">เมื่อชีวิตหนึ่งเดินทางถึงปลายทาง ตำนานและเรื่องเล่าระหว่างทางจะถูกเก็บไว้ที่นี่</p></div>'}<p style="color:var(--muted);font-size:11px">บันทึกเก็บบนเบราว์เซอร์นี้เท่านั้น เก็บสูงสุด 50 ชีวิต ส่งออกเซฟเพื่อย้ายอุปกรณ์หรือสำรองข้อมูลได้</p>`;document.querySelectorAll('[data-memory]').forEach(b=>b.onclick=()=>{const s=archive[+b.dataset.memory];LegacyUI.open(s)})}
// Original, locally drawn pixel art. Deterministic appearance stays consistent within one life.
function drawPerson(c,x,y,scale,s){Illustration.drawPerson(c,x,y,scale,s,Engine.biological(s))}
function drawPortrait(){Illustration.drawPortrait($('#portrait'),state)}
let sceneMotion=!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches),lastSceneFrame=0,sceneElapsed=0;
try{const saved=localStorage.getItem('aether-scene-motion');if(saved!==null)sceneMotion=saved==='on'}catch(e){}
function drawScene(){Illustration.drawScene($('#scene'),state,sceneElapsed);const button=$('#sceneMotion');if(button){button.textContent=sceneMotion?'❚❚ ภาพเคลื่อนไหว':'▶ ภาพเคลื่อนไหว';button.setAttribute('aria-pressed',String(sceneMotion));button.onclick=()=>{sceneMotion=!sceneMotion;try{localStorage.setItem('aether-scene-motion',sceneMotion?'on':'off')}catch(e){}drawScene()}}}
function animateScene(now){if(now-lastSceneFrame<125)return;const dt=Math.min(.25,(now-lastSceneFrame)/1000);lastSceneFrame=now;if(!sceneMotion||document.hidden||screen!=='playing'||tab!=='life'||$('#modal').open||clock.status().paused)return;const canvas=$('#scene');if(!canvas)return;const box=canvas.getBoundingClientRect();if(box.bottom<0||box.top>window.innerHeight)return;sceneElapsed+=dt;Illustration.drawScene(canvas,state,sceneElapsed)}
document.querySelector('.brand').onclick=e=>{e.preventDefault();if(screen==='rolling')return;screen='welcome';render()};
$('#close').onclick=()=>DecisionPopup.dismiss();$('#modal').addEventListener('cancel',e=>{if($('#modal').dataset.mode==='decision'){e.preventDefault();DecisionPopup.dismiss()}});$('#modal').addEventListener('close',()=>DecisionPopup.closed());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))DecisionPopup.dismiss()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;if(tab==='world')worldType='map';render()});
$('#help').onclick=()=>modal(`<div class="overline">A GUIDE TO A LIFE YOU CAN LIVE</div><h2>เปิดชาติกำเนิด แล้วค่อยเริ่มชีวิต</h2><p>กดสุ่มเพื่อชมการหมุนชาติกำเนิด อ่านชื่อ–นามสกุล เผ่า อาณาจักร และครอบครัวก่อนเลือก “ใช้ชีวิตชาตินี้” หรือ “สุ่มเกิดใหม่” ระหว่างอ่านใบกำเนิดจะไม่มีเวลาเดินและไม่มีการตัดสินใจอัตโนมัติ</p><p>ตัวละครเติบโตทั้งรูปร่างและทักษะตามวัยของเผ่า เผ่าอายุสั้นยังเป็นเด็กเมื่ออายุ 4 ปี และไม่เริ่มบทบาทผู้ใหญ่ก่อนวัย เรียนในชุมชน ฝึกช่าง หรือสมัครสถาบันได้เมื่อมีเหตุการณ์ทางการศึกษา งานสะสมความชำนาญและมีระดับความรับผิดชอบ เมื่อเริ่ม ชีวิตมีปฏิทินของตัวเอง เรื่องทั่วไปเกิดขึ้นระหว่างปีโดยไม่ต้องเลือก แต่ละปีมีเหตุการณ์อย่างน้อยสี่ช่วง ได้แก่เดือน 1, 4, 7 และ 10 การกินอยู่ การเรียนรู้ งาน ผู้คน และเหตุการณ์เล็ก ๆ จะเพิ่มในฟีดเรื่องราว ระบบจะหยุดเฉพาะจุดเปลี่ยนสำคัญ เช่น การเรียน ความรัก ความขัดแย้ง และครอบครัว</p><p>คุณเกิดมาพร้อมสมาชิกครอบครัวที่มีชื่อ อาชีพ บุคลิก และระดับความไว้ใจของตนเอง เลือกใช้ช่วงว่างเพื่ออยู่กับครอบครัว สำรวจเมือง ฝึกทักษะ หรือพักได้หนึ่งครั้งต่อช่วงเวลา ส่วนเหตุการณ์สำคัญจะเกิดตามเผ่า อาณาจักร ชนชั้น อาชีพ และแบบบ้านที่คุณสุ่มได้ ผลของคำตอบจะถูกจดไว้ในสมุดชีวิต</p><p>แผนที่ในหน้าสารานุกรมแสดงทั้งจุดเกิดและเมืองที่ไปอยู่ ฉากพิกเซลเปลี่ยนสีภูมิประเทศ อาคาร เวลา ฤดูกาล และสัญลักษณ์ตามเหตุการณ์ล่าสุด</p><p>ค่าเริ่มต้นให้คุณตอบเรื่องสำคัญเอง หากอยากเฝ้าดูทั้งหมด เปิด “ตัดสินใจแทน” ได้ ปรับความเร็ว 1–16 เท่าและจังหวะอ่านได้ เวลาต่อชีวิตเป็นค่าประมาณ โดยความเร็วที่เลือกใช้กับทั้งเวลา เรื่องเล่า และการอ่านผลอัตโนมัติ ปุ่มไปเหตุการณ์ถัดไปจะข้ามไปหยุดที่คำถามสำคัญ</p><p>มี ${RACES.length} เผ่า ${KINGDOMS.length} อาณาจักรและ ${JOBS.length} อาชีพ รวมถึงกิจการ ${Livelihood.businessCatalog.length} แบบ ชื่อสร้างจากรากคำเฉพาะเผ่าและรากตระกูลของอาณาจักร มีชุดผสมจำนวนมากแต่ไม่รับประกันว่าไม่ซ้ำทั่วโลก เปิดกิจการจากเมนูอาชีพ / กิจการได้เมื่อมีวัย ทักษะ และเงินทุนพอ บัญชีร้านเดินอัตโนมัติ มีทั้งรายรับ ต้นทุน ค่าจ้าง และโอกาสปิดร้าน บทสนทนาเปลี่ยนตามวัย ความไว้ใจ และประวัติการพูดคุย เนื้อหาชีวิตเป็นงานเขียนที่เลือกตามสถานะ ไม่ใช่ AI สร้างสดและยังพบข้อความซ้ำได้</p><p>โฟกัสรายปีมีทั้งการเรียน ครอบครัว สุขภาพ ความสุข งาน และเป้าหมายเฉพาะเผ่า เช่น การทูตของก๊อบลินหรือการปกป้องรังของมังกร เลือกอารมณ์และแนวทางชีวิตได้ ผลค่อย ๆ เกิดเมื่อเวลาผ่านไป ซื้อของใช้และเลือกงานอดิเรกจากเมนูบ้าน ส่วนเมนูสัตว์เลี้ยงเลือกสหาย ดูแล ฝึก หรือหาบ้านใหม่ให้ได้ สถานะในชนชั้น ความไว้ใจ และความสัมพันธ์กับชุมชนเปลี่ยนจากการเลือกจริง</p><p>ฉากพิกเซลมี ${SceneCatalog.stats.locations} สถานที่ใน ${KINGDOMS.length} อาณาจักร รวม ${SceneCatalog.stats.scenes} รูปแบบ ทั้งบ้าน ที่ทำงาน เรือ ชายทะเล ภูเขา และการข้ามแดน สีสถาปัตยกรรม เวลา อากาศ ตัวละคร สหาย และของที่ซื้อเปลี่ยนองค์ประกอบเพิ่มได้</p><p>เป้าหมายระยะยาวแบ่งเป็นสามช่วง เลือกเริ่มได้ตามวัย เผ่า และเส้นทางชีวิต ความคืบหน้าเดินตามโฟกัสรายปี เมื่อถึงจุดเปลี่ยนเกมจะหยุดให้ตัดสินใจ ผลของแต่ละช่วงและบทสรุปจะอยู่ในสมุดชีวิต คุณค้นหาบันทึกตามอายุ ประเภท หรือคำค้น และย้อนดูภาพรูปลักษณ์ที่เก็บไว้ในวันนั้นได้ ภาพเก่าที่ไม่ได้เก็บข้อมูลตัวละครจะแสดงเพียงสถานที่ประกอบ</p><p>เซฟอยู่ในเบราว์เซอร์ ใช้ฐานข้อมูลบนอุปกรณ์และสำรองชีวิตปัจจุบันใน localStorage ส่งออกเซฟก่อนล้างเบราว์เซอร์หรือย้ายอุปกรณ์ เปิดเมนู เปลี่ยนหน้าหรือซ่อนแท็บจะพักเวลา ไม่มีการเดินชีวิตย้อนหลังขณะปิดเว็บ</p>`);
$('#sound').onclick=async()=>{if(soundOn){clearInterval(musicTimer);soundOn=false;await audio.suspend()}else{try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();await audio.resume();soundOn=true;const play=()=>{const t=audio.currentTime;[220,261.63,329.63,392].forEach((freq,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,t+i*.25);g.gain.linearRampToValueAtTime(.018,t+i*.25+.12);g.gain.exponentialRampToValueAtTime(.0001,t+i*.25+3);o.connect(g);g.connect(audio.destination);o.start(t+i*.25);o.stop(t+i*.25+3.1)})};play();musicTimer=setInterval(play,4500)}catch(e){toast('เบราว์เซอร์นี้ยังเปิดเสียงไม่ได้');return}}$('#sound').innerHTML='♫ <span>'+(soundOn?'เสียงเปิด':'เสียงปิด')+'</span>'};
document.addEventListener('keydown',e=>{if(screen!=='playing'||tab!=='life'||$('#modal').open||state.dead||e.repeat)return;if(['1','2','3','4'].includes(e.key)&&state.calendar?.pending&&!state.outcome){if(Simulation.choose(state,+e.key-1)){record();clock.reset();render()}}else if(e.key==='Enter'&&state.outcome){state.outcome=null;clock.reset();render()}});
let lastClockPaint=0;
function animateIntro(now){if(now-lastIntroFrame<125)return;const dt=Math.min(.25,(now-lastIntroFrame)/1000);lastIntroFrame=now;if(!sceneMotion||document.hidden||screen==='playing'||$('#modal').open)return;const canvas=$('#welcomeScene')||$('#birthPreview')||$('#rollPreview');if(!canvas)return;const box=canvas.getBoundingClientRect();if(box.bottom<0||box.top>window.innerHeight)return;introElapsed+=dt;drawIntroArt()}
function animateLife(now){clock.frame(now);animateScene(now);animateIntro(now);if(now-lastClockPaint>100){paintClock();lastClockPaint=now}requestAnimationFrame(animateLife)}
document.addEventListener('visibilitychange',()=>{clock.reset();save(document.hidden);if(document.hidden&&storageReady)LifeStorage.flush().catch(()=>{})});
window.addEventListener('pagehide',()=>{save(true);if(storageReady)LifeStorage.flush().catch(()=>{})});
async function bootLife(){try{const data=await LifeStorage.load();const histories=Array.isArray(data.archive)?data.archive:[];if(histories.length>50)throw Error('Invalid archive');histories.forEach(Engine.hydrate);archive=histories;if(data.life){const restored=Engine.hydrate(data.life);const databaseTime=Number(restored.savedAt)||0,backupTime=Number(state?.savedAt)||0;if(databaseTime>backupTime||databaseTime===backupTime&&(Number(restored.saveRevision)||0)>=(Number(state?.saveRevision)||0))state=restored;Narrative.ensure(state)}storageReady=true}catch(e){}record();render();requestAnimationFrame(animateLife);if(storageFailed)toast('ใช้บันทึกสำรองที่อ่านได้ โปรดส่งออกเซฟเก็บไว้ด้วย')}

if(window.indexedDB){app.innerHTML='<section class="panel empty">กำลังเปิดสมุดชีวิต…</section>';bootLife()}else{record();render();requestAnimationFrame(animateLife);if(storageFailed)toast('อ่านเซฟเดิมไม่ได้ โปรดตรวจบันทึกและส่งออกสำรอง')}


GameLanguage.bindState(()=>state,()=>{if(screen==='playing'){if(tab==='life'){drawPortrait();drawScene()}else if(tab==='archive')document.querySelectorAll('[data-legacy-scene]').forEach(()=>{})}else drawIntroArt()});
